const promptExcerpt=(text:string,limit:number,source:string)=>text.length>limit?`${text.slice(0,limit)}\n[Excerpt: ${limit}/${text.length} characters. Read ${source} for the full retained record.]`:text;
const runtimeEvidence=(result:RuntimeResult)=>({text:result.text,modelIdentity:result.artifactIdentity,usage:result.usage,messagesPath:result.messagesPath,runtimeCompletion:result.completion,runtimeDiagnosticsPath:result.diagnosticsPath});
/** Corporate-only mode is restricted to scheduler-owned formation and its trusted fault recovery. */
export function corporateOnlyFormation(store:CompanyStore,run:EmployeeRun):boolean {
 const formation=(assignment:Assignment)=>assignment.kind==='management'&&assignment.projectId===null&&assignment.payload?.formation===true&&/^formation:(?:office:.+|department:.+|recruiter-bootstrap|(?:request|candidate|approve|provision|onboard):.+)$/.test(assignment.schedulerKey??'');
 const assignment=store.get('assignments',run.assignmentId);if(!assignment||assignment.employeeId!==run.employeeId)return false;
 if(formation(assignment))return true;
 const fault=store.faultContext(run.id);return assignment.projectId===null&&!!fault&&formation(fault.assignment);
}
export function assignmentAnchor(assignment:Pick<Assignment,'id'|'kind'|'projectId'>&{payload?:{artifactId?:unknown};schedulerKey?:string}):string {
 const artifactId=assignment.kind==='review'&&typeof assignment.payload?.artifactId==='string'&&assignment.payload.artifactId.length<=128?assignment.payload.artifactId:undefined;
 const task={assignmentId:assignment.id,kind:assignment.kind,...(assignment.projectId?{projectId:assignment.projectId}:{}),...(artifactId?{artifactId}:{})};
 const retrieve=JSON.stringify({collection:'assignments',id:assignment.id,offset:0});
 return `Durable assignment anchor: ${JSON.stringify(task)}. After compaction or lost task context, call company_detail ${retrieve} and follow nextOffset to recover the exact stored instructions, acceptance and progress; inspect its linked scoped records as needed. Continue this stored assignment, not a new direction inferred from a summary.\n${assignment.kind==='management'&&assignment.schedulerKey?.startsWith('formation:')?'This is company formation work. The assigned corporate action, recorded through company tools, is the deliverable. It may already be retained from an earlier interrupted run. Inspect only missing evidence needed to establish that the specific assigned action is fulfilled. Once fulfilled, briefly summarize its actual record IDs and result, then end the run. Do not repeat the action, create a product artifact, or manually change assignment status to justify ending. The scheduler verifies the retained outcome; a summary alone never substitutes for a missing required action.\n':''}${assignment.kind==='review'?`This is an independent review assignment. ${artifactId?`Read company_detail ${JSON.stringify({collection:'artifacts',id:artifactId,view:'record',offset:0})}`:'Read the artifact identified by the stored payload.artifactId with company_detail view record'} and then its original assignmentId with company_detail assignments for the exact original acceptance. Complete actual independent inspect_artifact coverage and inspect the retained checks, then call review_work with that artifactId, verdict approved or changes_requested, and concrete rationale. Record approved or changes_requested based on actual evidence and original acceptance; do not claim unobserved completion. Approval itself does not mean the original assignment, future delivery or release has completed. Final prose or a request for new directions is not the required review verdict.`:''}`;
}
type DependencyState={id:string;status:string};
const sameDependencies=(left:string[],right:string[])=>left.length===right.length&&left.every(id=>right.includes(id));
const dependencyWaitKey=(target:Pick<Assignment,'id'|'supervisorId'|'projectId'>,states:DependencyState[])=>`dependency-wait:${target.id}:${createHash('sha256').update(JSON.stringify([target.supervisorId,target.projectId,[...states].sort((a,b)=>a.id.localeCompare(b.id)).map(item=>[item.id,item.status])])).digest('hex')}`;
/** Existing shared-staffing authority may require a common supervising manager. */
function acceptanceCoordinator(store:CompanyStore,assignment:Assignment):Employee|undefined {
 const project=assignment.projectId?store.get('projects',assignment.projectId):undefined;if(!project)return;
 const seen=new Set<string>();let candidate=store.get('employees',assignment.supervisorId);
 while(candidate&&!seen.has(candidate.id)){
  seen.add(candidate.id);const actor:Actor={kind:'employee',employeeId:candidate.id,runId:'scheduler',policyRevision:store.policy.revision};
  if(candidate.status==='active'&&['ceo','executive','lead','manager'].includes(store.level(candidate.id))&&(candidate.id===assignment.supervisorId||store.canManage(actor,assignment.supervisorId))&&(candidate.id===project.supervisorId||store.canManage(actor,project.supervisorId)))return candidate;
  candidate=candidate.homeManagerId?store.get('employees',candidate.homeManagerId):undefined;
 }
}

/** A recovery can inspect its own unfinished vote, but cannot expose a peer's judgment. */
export function governanceDispatchAllowed(store:CompanyStore,assignment:Assignment,employeeId=assignment.employeeId,requireOwnVote=false):boolean {
 const seen=new Set<string>();let current:Assignment|undefined=assignment;
 while(current){
  if(seen.has(current.id))return false;seen.add(current.id);
  if(current.kind==='governance'||current.schedulerKey?.startsWith('governance-application:')){
   const applicationCorrection:boolean=current.schedulerKey?.startsWith('governance-application:')===true;if(applicationCorrection)requireOwnVote=true;
   const decision:Decision|undefined=store.get('decisions',applicationCorrection?current.payload?.sourceDecisionId:current.payload?.decisionId);
   if(decision?.eligibleElders?.includes(employeeId)&&(requireOwnVote||current.employeeId!==employeeId)&&!store.list('votes').some(vote=>vote.decisionId===decision.id&&vote.employeeId===employeeId))return false;
   const originRun:EmployeeRun|undefined=decision?.runId?store.get('runs',decision.runId):decision?store.list('runs').find(run=>(run.corporateCommands??[]).some((command:any)=>command.type==='decision.create'&&command.id===decision.id)):undefined;
   current=originRun?store.get('assignments',originRun.assignmentId):undefined;requireOwnVote=true;
  }else{
   const origin=store.assignmentOrigin(current);
   current=origin?store.get('assignments',origin):undefined;
  }
 }
 return true;
}

