  const assignment=this.store.put('assignments',{employeeId:employee.id,supervisorId,projectId:input.projectId??null,title:input.title,instructions:input.instructions,acceptance:input.acceptance??['Record the requested outcome through corporate tools with source-linked reasons.'],dependencies:[],status:'queued',priority:input.priority??5,attempts:0,corrections:0,kind:input.kind??'management',availableAt:new Date().toISOString(),accepted,payload:input.payload??{},schedulerKey:input.key});this.store.emit('assignment.scheduled',{assignmentId:assignment.id,employeeId:employee.id});
