   let correction=this.store.assignmentBySchedulerKey(key)!;
   if(correction.status==='queued'&&correction.employeeId!==coordinator.id&&!active.has(correction.id))correction=this.store.update('assignments',correction.id,{employeeId:coordinator.id,supervisorId:coordinator.homeManagerId??coordinator.id,reviewScopeRoutingHistory:[...(correction.reviewScopeRoutingHistory??[]),{at:new Date().toISOString(),priorEmployeeId:correction.employeeId,priorSupervisorId:correction.supervisorId,employeeId:coordinator.id,reason:'Existing supervisory authority or evidence access changed before dispatch.'}]});
   if(target.reviewScopeRecovery?.assignmentId!==correction.id||target.reviewScopeRecovery?.employeeId!==correction.employeeId)this.store.update('assignments',target.id,{reviewScopeRecovery:{state:'assigned',assignmentId:correction.id,employeeId:correction.employeeId,at:new Date().toISOString()}});
